                if (disasm_info.buffer_length <= (size_t) octets)
                    break;
                disasm_info.buffer += octets;
                disasm_info.buffer_vma += octets / disasm_info.octets_per_byte;
                disasm_info.buffer_length -= octets;
            }
            disassemble_free_target(&disasm_info);
